    ],
    "factor_sequence": [
      "O4",
      "O1"
    ]
  },
  {
    "statement": "For two proteins with identical native structures and identical lengths, their TM-scores to the same reference structure are identical.",
    "motivation": "This repairs the gap by adding the length equality condition, making the TM-score comparison well-defined under O4. It preserves the core intuition while being provable from O1 and O4.",
    "depends_on": [
      "O1",
      "O4"
    ],
    "factor_sequence": [
      "O1",
      "O4"
    ]
  },
  {
    "statement": "If two proteins have identical native structures, then for any reference structure R, the difference in their TM-scores to R is bounded by a function of their length difference.",
    "motivation": "This explores a quantitative weakening of the original hypothesis, acknowledging the length dependence in O4 while still deriving a non-trivial constraint from structural identity.",
    "depends_on": [
      "O1",
      "O4"
    ],
    "factor_sequence": [
      "O1",
      "O4"
    ]
  },
  {
    "statement": "For two proteins with identical native structures, their TM-scores to their own native structures are both 1.0 (by definition).",
    "motivation": "This focuses on the self-comparison case where the reference structure is the native structure itself, which is directly implied by O4's normalization and avoids length-comparison issues.",
    "depends_on": [
      "O1",
      "O4"
    ],
    "factor_sequence": [
      "O1",
      "O4"
    ]
  },
  {
    "statement": "For two proteins with identical native structures (global minima per O1), their TM-scores when comparing their native structures to EACH OTHER are 1.0.",
    "motivation": "This is a minimal, checkable repair that avoids the superposition invariance gap. If the native structures are identical, aligning one to the other trivially gives perfect residue correspondence (d_i=0 for all i), leading to TM-score=1. This follows directly from O4's definition without extra assumptions about superposition against arbitrary references.",
    "depends_on": [
      "O1",
      "O4"
    ],
    "factor_sequence": [
      "O1",
      "O4"
    ]
  },
  {
    "statement": "For two proteins with identical native structures, their TM-scores to a COMMON reference structure are identical IF the optimal superposition for that reference is the same for both proteins.",
    "motivation": "This makes the hidden assumption explicit as a conditional premise. It isolates the superposition invariance as a required condition, turning the original hypothesis into a testable implication. This follows the HPA principle of exposing gaps δ as explicit lemmas.",
    "depends_on": [
      "O1",
      "O4"
    ],
    "factor_sequence": [
      "O1",
      "O4"
    ]
  },
  {
    "statement": "For a single protein, the TM-score between its native structure (per O1) and itself is 1.0.",
    "motivation": "This is an even more minimal, foundational check. It tests the consistency of O1 and O4 without involving multiple proteins. It's a direct consequence of O4's definition when the two structures being compared are identical (d_i=0), and O1 ensures the native structure is a well-defined entity.",
    "depends_on": [
      "O1",
      "O4"
    ],
    "factor_sequence": [
      "O1",
      "O4"
    ]
  }
]

